out={};allmiss=[]
for (ex,n),areas in SPEC.items():
    for area,phr in areas.items():
        rects,miss=find(ex,n,phr)
        out.setdefault(f'{ex}-{n}',{})[area]=rects
        if miss: allmiss.append((ex,n,area,miss))
        if not rects: allmiss.append((ex,n,area,'NO RECTS'))
json.dump(out,open('/home/claude/past/hl.json','w'),ensure_ascii=False)
for m in allmiss: print('MISS',m)
print({k:{a:len(v) for a,v in d.items()} for k,d in out.items()})
